CREATE TYPE "RFQStatus" AS ENUM ('DRAFT','READY_TO_SEND','ISSUED','RESPONSES_PENDING','EVALUATION','CLOSED','CANCELLED','EXPIRED');
CREATE TYPE "RFQRecipientStatus" AS ENUM ('PENDING','SENT','RESPONDED','DECLINED','CANCELLED');
CREATE TYPE "SupplierQuoteStatus" AS ENUM ('RECEIVED','UNDER_REVIEW','ACCEPTED','REJECTED','EXPIRED');
CREATE TYPE "PurchaseCostApprovalStatus" AS ENUM ('PENDING','APPROVED','REJECTED','SUPERSEDED');
CREATE TABLE rfqs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), status "RFQStatus" NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL REFERENCES "User"(id), issued_by UUID REFERENCES "User"(id), issued_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, related_rfq_id UUID REFERENCES rfqs(id), internal_notes TEXT, correlation_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rfq_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id UUID NOT NULL REFERENCES rfqs(id) ON DELETE RESTRICT, execution_item_id UUID NOT NULL REFERENCES procurement_execution_items(id) ON DELETE RESTRICT, company_id UUID NOT NULL REFERENCES "Company"(id), project_id UUID REFERENCES projects(id), procurement_need_id UUID NOT NULL REFERENCES procurement_needs(id), product_identity_id UUID NOT NULL REFERENCES product_identities(id), requested_quantity NUMERIC(18,4) NOT NULL CHECK(requested_quantity>0), unit_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(rfq_id,execution_item_id));
CREATE TABLE rfq_recipients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id UUID NOT NULL REFERENCES rfqs(id) ON DELETE RESTRICT, purchase_source_id UUID NOT NULL REFERENCES purchase_sources(id) ON DELETE RESTRICT, supplier_company_id UUID NOT NULL REFERENCES "Company"(id), status "RFQRecipientStatus" NOT NULL DEFAULT 'PENDING', sent_at TIMESTAMPTZ, responded_at TIMESTAMPTZ, declined_at TIMESTAMPTZ, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(rfq_id,purchase_source_id));
CREATE TABLE supplier_quotes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id UUID NOT NULL REFERENCES rfqs(id) ON DELETE RESTRICT, purchase_source_id UUID NOT NULL REFERENCES purchase_sources(id), supplier_company_id UUID NOT NULL REFERENCES "Company"(id), received_at TIMESTAMPTZ NOT NULL DEFAULT now(), quote_reference TEXT, status "SupplierQuoteStatus" NOT NULL DEFAULT 'RECEIVED', source_context TEXT NOT NULL DEFAULT 'MANUAL', created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier_quote_revisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_quote_id UUID NOT NULL REFERENCES supplier_quotes(id) ON DELETE RESTRICT, revision_number INTEGER NOT NULL CHECK(revision_number>0), supersedes_revision_id UUID REFERENCES supplier_quote_revisions(id), initiated_by UUID NOT NULL REFERENCES "User"(id), reason TEXT, currency_code TEXT NOT NULL, valid_until DATE, payment_term_type TEXT, original_terms_text TEXT, advance_percentage NUMERIC(7,4), credit_days INTEGER, milestone_description TEXT, source_document_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(supplier_quote_id,revision_number));
CREATE TABLE supplier_quote_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), revision_id UUID NOT NULL REFERENCES supplier_quote_revisions(id) ON DELETE RESTRICT, rfq_item_id UUID NOT NULL REFERENCES rfq_items(id) ON DELETE RESTRICT, product_identity_id UUID NOT NULL REFERENCES product_identities(id), quoted_quantity NUMERIC(18,4) NOT NULL CHECK(quoted_quantity>0), unit_id UUID, unit_price_excl_tax NUMERIC(18,6) NOT NULL CHECK(unit_price_excl_tax>=0), tax_amount NUMERIC(18,6), tax_rate NUMERIC(9,6), amount_incl_tax NUMERIC(18,6), tax_included BOOLEAN, supplier_item_reference TEXT, availability TEXT, lead_time TEXT, warranty TEXT, notes TEXT, UNIQUE(revision_id,rfq_item_id));
CREATE TABLE negotiation_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id UUID NOT NULL REFERENCES rfqs(id), status TEXT NOT NULL DEFAULT 'OPEN', created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), closed_at TIMESTAMPTZ);
CREATE TABLE negotiation_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID NOT NULL REFERENCES negotiation_sessions(id) ON DELETE RESTRICT, supplier_quote_revision_id UUID REFERENCES supplier_quote_revisions(id), direction TEXT NOT NULL, event_type TEXT NOT NULL, reason TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, actor_user_id UUID NOT NULL REFERENCES "User"(id), correlation_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE alternative_product_proposals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_item_id UUID NOT NULL REFERENCES rfq_items(id), proposed_product_identity_id UUID REFERENCES product_identities(id), supplier_reference TEXT, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING_REVIEW', reviewed_by UUID REFERENCES "User"(id), reviewed_at TIMESTAMPTZ, decision_reason TEXT, created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE approved_purchase_cost_snapshots (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rfq_item_id UUID NOT NULL REFERENCES rfq_items(id), supplier_quote_revision_id UUID NOT NULL REFERENCES supplier_quote_revisions(id), purchase_source_id UUID NOT NULL REFERENCES purchase_sources(id), supplier_company_id UUID NOT NULL REFERENCES "Company"(id), product_identity_id UUID NOT NULL REFERENCES product_identities(id), approved_quantity NUMERIC(18,4) NOT NULL CHECK(approved_quantity>0), currency_code TEXT NOT NULL, unit_purchase_cost NUMERIC(18,6) NOT NULL CHECK(unit_purchase_cost>=0), amount_excl_tax NUMERIC(18,6) NOT NULL, tax_amount NUMERIC(18,6), amount_incl_tax NUMERIC(18,6), tax_included BOOLEAN, payment_terms JSONB, delivery_terms JSONB, warranty TEXT, status "PurchaseCostApprovalStatus" NOT NULL DEFAULT 'PENDING', approved_by UUID REFERENCES "User"(id), approved_at TIMESTAMPTZ, approval_reason TEXT, correlation_id TEXT, supersedes_snapshot_id UUID REFERENCES approved_purchase_cost_snapshots(id), created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX rfq_items_execution_idx ON rfq_items(execution_item_id); CREATE INDEX quote_revisions_quote_idx ON supplier_quote_revisions(supplier_quote_id); CREATE INDEX cost_snapshots_item_idx ON approved_purchase_cost_snapshots(rfq_item_id);
GRANT SELECT,INSERT,UPDATE ON rfqs,rfq_items,rfq_recipients,supplier_quotes,supplier_quote_revisions,supplier_quote_items,negotiation_sessions,negotiation_events,alternative_product_proposals,approved_purchase_cost_snapshots TO sco_runtime;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['rfqs','rfq_items','rfq_recipients','supplier_quotes','supplier_quote_revisions','supplier_quote_items','negotiation_sessions','negotiation_events','alternative_product_proposals','approved_purchase_cost_snapshots'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I_internal ON %I FOR ALL TO sco_runtime USING (current_setting(''app.sco_internal'',true)=''true'') WITH CHECK (current_setting(''app.sco_internal'',true)=''true'')',t,t); END LOOP; END $$;
INSERT INTO "Permission" (id,code,description) VALUES (gen_random_uuid(),'rfq.create','Create RFQs'),(gen_random_uuid(),'rfq.issue','Issue RFQs'),(gen_random_uuid(),'rfq.cancel','Cancel RFQs'),(gen_random_uuid(),'quote.record','Record supplier quotes'),(gen_random_uuid(),'quote.revise','Revise supplier quotes'),(gen_random_uuid(),'negotiation.record','Record negotiations'),(gen_random_uuid(),'source.select','Select purchase source'),(gen_random_uuid(),'purchase_cost.approve','Approve purchase cost'),(gen_random_uuid(),'purchase_cost.self_approve','Self-approve purchase cost') ON CONFLICT(code) DO NOTHING;
CREATE OR REPLACE FUNCTION enforce_purchase_cost_quantity() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE requested NUMERIC; allocated NUMERIC; BEGIN IF NEW.status='APPROVED' THEN SELECT requested_quantity INTO requested FROM rfq_items WHERE id=NEW.rfq_item_id FOR UPDATE; SELECT COALESCE(SUM(approved_quantity),0) INTO allocated FROM approved_purchase_cost_snapshots WHERE rfq_item_id=NEW.rfq_item_id AND status='APPROVED' AND id<>NEW.id; IF allocated + NEW.approved_quantity > requested THEN RAISE EXCEPTION 'APPROVED_QUANTITY_EXCEEDED'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER purchase_cost_quantity_guard BEFORE INSERT OR UPDATE OF status,approved_quantity,rfq_item_id ON approved_purchase_cost_snapshots FOR EACH ROW EXECUTE FUNCTION enforce_purchase_cost_quantity();
